import{_ as t,o,c as r,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const c=JSON.parse('{"title":"Hardware requirements","description":"","frontmatter":{"title":"Hardware requirements"},"headers":[],"relativePath":"docs/overview/hardware-requirements.md","filePath":"docs/overview/hardware-requirements.md","lastUpdated":1793412416000}'),s={name:"docs/overview/hardware-requirements.md"};function n(i,e,d,h,l,m){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="hardware-requirements" tabindex="-1">Hardware requirements <a class="header-anchor" href="#hardware-requirements" aria-label="Permalink to &quot;Hardware requirements&quot;">​</a></h1><p>These requirements are only for running a <strong>local</strong> built-in model — the whole point of which is to work fully offline with nothing leaving your machine.</p><h2 id="which-model-you-get" tabindex="-1">Which model you get <a class="header-anchor" href="#which-model-you-get" aria-label="Permalink to &quot;Which model you get&quot;">​</a></h2><p>When you first set up OrbySystems, it chooses a built-in model from how much memory your computer has. You can change it at any time in <a href="./../settings/models">Settings → Models</a>.</p><table tabindex="0"><thead><tr><th>Your computer&#39;s memory</th><th>The model OrbySystems chooses</th><th>Context</th></tr></thead><tbody><tr><td>Less than 16 GB (8 or 12 GB)</td><td><strong>OrbySystems Small</strong></td><td>32,768 tokens</td></tr><tr><td>16 GB or more</td><td><strong>OrbySystems Medium</strong></td><td>Sized to your memory: about 183,000 tokens on a 16 GB Mac at the default setting</td></tr></tbody></table><p><em>Context</em> is how much of a conversation, and of the data it draws on, the model can keep in mind at once. Each model card in Settings → Models offers low, medium and high; a higher setting holds more and uses more memory.</p><p><strong>OrbySystems Large</strong> is a bigger, more capable model you can choose yourself on a computer with plenty of memory to spare: it needs about 12 GB for the model alone at its usual context.</p><h2 id="how-much-memory-the-model-uses" tabindex="-1">How much memory the model uses <a class="header-anchor" href="#how-much-memory-the-model-uses" aria-label="Permalink to &quot;How much memory the model uses&quot;">​</a></h2><p>Measured on an Apple M1 Mac with 16 GB of memory:</p><table tabindex="0"><thead><tr><th></th><th>OrbySystems Small</th><th>OrbySystems Medium</th></tr></thead><tbody><tr><td>While answering, usually</td><td>about 4 GB</td><td>about 7.6 GB</td></tr><tr><td>At its busiest</td><td>about 6 GB</td><td>about 10 GB</td></tr></tbody></table><p>Each model card in Settings → Models shows the estimate for your own computer at the setting you have chosen.</p><h2 id="computers-with-less-than-16-gb" tabindex="-1">Computers with less than 16 GB <a class="header-anchor" href="#computers-with-less-than-16-gb" aria-label="Permalink to &quot;Computers with less than 16 GB&quot;">​</a></h2><p>Where the model shares your computer&#39;s memory — any Mac, or a PC without a graphics card that can hold the model — OrbySystems Small keeps to 32,768 tokens at every setting, to leave the rest of the computer as much memory as it can. Its model card says so. Closing other memory-hungry apps while you chat helps.</p><h2 id="graphics-cards-and-unified-memory" tabindex="-1">Graphics cards and unified memory <a class="header-anchor" href="#graphics-cards-and-unified-memory" aria-label="Permalink to &quot;Graphics cards and unified memory&quot;">​</a></h2><p>OrbySystems detects which kind of memory your computer has and sizes the model to it:</p><ul><li><strong>A graphics card with memory of its own</strong> (most Windows and Linux gaming and workstation cards). The model runs on the card when the card has room for it — about 4.6 GB free for Small, 5.2 GB for Medium and 9.2 GB for Large — and keeps its context in the card&#39;s memory, not your computer&#39;s. On a smaller card the model runs on the processor instead, which works but is slower.</li><li><strong>Unified memory</strong> (Apple silicon Macs). The model shares the Mac&#39;s memory with everything else, so the figures above come out of your Mac&#39;s total.</li></ul><p><em>Hint</em>: the <a href="./../settings/models">Settings → Models</a> page shows what OrbySystems found when it starts: the graphics card or unified memory it sees, and how much context each model card has room for.</p><h2 id="docling-document-ingestion" tabindex="-1">Docling (document ingestion) <a class="header-anchor" href="#docling-document-ingestion" aria-label="Permalink to &quot;Docling (document ingestion)&quot;">​</a></h2><p>Docling is the local service OrbySystems uses to convert PDFs and other documents into text for ingestion (and to re-read a page&#39;s layout when redacting it — see the <a href="/docs/tools/pii-redactor">PII Redactor</a>). It&#39;s deliberately <strong>CPU-only</strong>: on a GPU, its layout/OCR models use a lot of VRAM — worst on image-heavy pages — for little wall-clock gain over CPU, and that VRAM is worth more to your local model. So Docling adds no VRAM requirement, but it does need roughly <strong>4 GB of free system RAM</strong> while it&#39;s running, on top of whatever your local model needs.</p><h2 id="presidio-pii-detection" tabindex="-1">Presidio (PII detection) <a class="header-anchor" href="#presidio-pii-detection" aria-label="Permalink to &quot;Presidio (PII detection)&quot;">​</a></h2><p>Presidio is OrbySystems&#39;s default engine for detecting personal information — used by the <a href="/docs/tools/pii-redactor">PII Redactor</a>. It&#39;s also <strong>CPU-only</strong>, and needs roughly <strong>1.5 GB of free system RAM</strong> while running.</p><h2 id="adding-it-up" tabindex="-1">Adding it up <a class="header-anchor" href="#adding-it-up" aria-label="Permalink to &quot;Adding it up&quot;">​</a></h2><p>Docling and Presidio are both started on demand — they only run (and only use this memory) while you&#39;re actually ingesting a document or checking/redacting PII, not for the whole time OrbySystems is open. If you do that alongside chatting with your local model, budget their memory on top of the model&#39;s: roughly <strong>+4 GB of system RAM while Docling is active</strong>, and <strong>+1.5 GB of system RAM while Presidio is active</strong> — both independent of whether your model itself runs on a dedicated GPU or unified memory, since these two always run on CPU/RAM regardless.</p><h2 id="if-your-hardware-falls-short" tabindex="-1">If your hardware falls short <a class="header-anchor" href="#if-your-hardware-falls-short" aria-label="Permalink to &quot;If your hardware falls short&quot;">​</a></h2><p>Nothing about OrbySystems requires a local model - you can connect to an external model running in the cloud or on a separate machine via a standard API endpoint instead (see <a href="/docs/settings/models">Settings → Models</a>). However, OrbySystems operates under the assumption that there is at least one <strong>trusted</strong> model configured that can be used to chat about your data. Be clear about which LLM services you trust.</p>',25)])])}const y=t(s,[["render",n]]);export{c as __pageData,y as default};
